import * as THREE from 'three';
import {roundedRect} from '../../core/geometry.js';
import {mesh} from '../../modeling/parts.js';
export function circleHole(shape,x,y,r){const p=new THREE.Path();p.absarc(x,y,r,0,Math.PI*2,false);shape.holes.push(p);}
export function solid(parent,shape,depth,position,material,name){return mesh(parent,new THREE.ExtrudeGeometry(shape,{depth,bevelEnabled:false,curveSegments:32}),material,position,name);}
export function frontContour(){const s=new THREE.Shape();s.moveTo(-8,-16);s.lineTo(-5.15,-16);s.lineTo(-5.15,-9.35);s.lineTo(5.15,-9.35);s.lineTo(5.15,-16);s.lineTo(8,-16);s.absarc(8,-12,4,-Math.PI/2,0,false);s.lineTo(12,12);s.absarc(8,12,4,0,Math.PI/2,false);s.lineTo(4.3,16);s.lineTo(4.3,5.25);s.lineTo(-4.3,5.25);s.lineTo(-4.3,16);s.lineTo(-8,16);s.absarc(-8,12,4,Math.PI/2,Math.PI,false);s.lineTo(-12,-12);s.absarc(-8,-12,4,Math.PI,Math.PI*1.5,false);s.closePath();return s;}
export function openRing(){const s=new THREE.Shape();s.moveTo(-5.15,-16);s.lineTo(-8,-16);s.absarc(-8,-12,4,-Math.PI/2,-Math.PI,true);s.lineTo(-12,12);s.absarc(-8,12,4,Math.PI,Math.PI/2,true);s.lineTo(8,16);s.absarc(8,12,4,Math.PI/2,0,true);s.lineTo(12,-12);s.absarc(8,-12,4,0,-Math.PI/2,true);s.lineTo(5.15,-16);s.lineTo(5.15,-14.8);s.lineTo(8,-14.8);s.absarc(8,-12,2.8,-Math.PI/2,0,false);s.lineTo(10.8,12);s.absarc(8,12,2.8,0,Math.PI/2,false);s.lineTo(-8,14.8);s.absarc(-8,12,2.8,Math.PI/2,Math.PI,false);s.lineTo(-10.8,-12);s.absarc(-8,-12,2.8,Math.PI,Math.PI*1.5,false);s.lineTo(-5.15,-14.8);s.closePath();return s;}
export function ringShape(w,h,r,innerW,innerH,innerR){const s=roundedRect(w,h,r);s.holes.push(roundedRect(innerW,innerH,innerR,{path:new THREE.Path(),clockwise:true}));return s;}
export function relief(parent,paths,{position=[0,0,0],material,width=.18,name}){const g=new THREE.Group();g.name=name;g.position.fromArray(position);parent.add(g);for(const points of paths){for(let i=1;i<points.length;i++){const a=new THREE.Vector3(...points[i-1],0),b=new THREE.Vector3(...points[i],0),d=b.clone().sub(a),o=mesh(g,new THREE.CylinderGeometry(width,width,d.length(),12),material,a.clone().add(b).multiplyScalar(.5).toArray(),name+' solid stroke');o.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());}}return g;}
